In dev/render.html renderTree(), replace the single link per family with a per-family fallback chain fetched with fetch(), and inject the CSS text into a <style>:

```js
const used = new Map(); // family -> Set of "ital,wght" tuples
(function walk(n){
  if (n.segments) for (const s of n.segments) {
    const it = /italic|oblique/i.test(s.font.style || '') || s.italic ? 1 : 0;
    const w = Math.round((s.fontWeight || s.font.weight || 400) / 100) * 100;
    for (const f of s.font.families) {
      if (!used.has(f)) used.set(f, new Set());
      used.get(f).add(it + ',' + w);
    }
  }
  (n.children || []).forEach(walk);
})(doc.root);
const G = 'https://fonts.googleapis.com/css2?display=block&family=';
const get = (q) => fetch(G + q).then((r) => (r.ok ? r.text() : Promise.reject(r.status)));
async function loadFamily(f) {
  const e = encodeURIComponent(f);
  const css = [];
  // 1) full variable range with italic, 2) full range without italic
  for (const q of [e + ':ital,wght@0,100..900;1,100..900', e + ':wght@100..900']) {
    try { css.push(await get(q)); break; } catch (_) {}
  }
  // 3) each used tuple on its own, so one missing weight or italic doesn't sink the rest
  //    (needed for static families such as Poppins, and to add italics in case 2)
  if (!css.length || ![...used.get(f)].every((t) => t[0] === '0')) {
    const r = await Promise.allSettled([...used.get(f)].map((t) => get(e + ':ital,wght@' + t)));
    r.forEach((x) => { if (x.status === 'fulfilled') css.push(x.value); });
  }
  // 4) last resort: the bare family (regular 400 only)
  if (!css.length) { try { css.push(await get(e)); } catch (_) {} }
  const st = document.createElement('style');
  st.textContent = css.join('\n');
  document.head.appendChild(st);
}
const links = [...used.keys()].filter((f) => !generic.test(f)).map(loadFamily);
```

